.site-header {
  position: sticky; /* forms a stacking context */
  top: 0;
}

.menu {
  position: absolute;
  z-index: 9999; /* ranks only inside .site-header */
}

.carousel {
  position: relative;
  z-index: 1; /* ranks in the root context */
}

:root {
  --z-carousel: 1;
  --z-header: 2;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: var(--z-header); /* compete at the right level */
}

.menu {
  position: absolute; /* no z-index needed */
}

.carousel {
  position: relative;
  z-index: var(--z-carousel);
}
